(1, 1, 'Root', 'root', '', 'Root Category Description', '', '', '', NULL, 'en'),
(2, 1, 'الرئيسية', 'root', '', 'وصف الفئة الرئيسية', '', '', '', NULL, 'ar'),
(3, 2, 'Mens', 'mens', 'men', '<p>Men</p>', '', '', '', NULL, 'en'),
(4, 3, 'Kids', 'kids', 'kids', '<p>Kids</p>', '', '', '', NULL, 'en'),
(5, 4, 'Womens', 'womens', 'woman', '<p>Woman</p>', '', '', '', NULL, 'en'),
(6, 5, 'Formal Wear', 'formal-wear-men', 'men/formal-wear-men', '<p>Formal Wear</p>', '', '', '', NULL, 'en'),
(7, 6, 'Casual Wear', 'casual-wear-men', 'men/casual-wear-men', '<p>Casual Wear</p>', '', '', '', NULL, 'en'),
(8, 7, 'Active Wear', 'active-wear', 'men/active-wear', '<p>Active Wear</p>', '', '', '', NULL, 'en'),
(9, 8, 'Footwear', 'footwear', 'men/footwear', '<p>Footwear</p>', '', '', '', NULL, 'en'),
(10, 9, 'Formal Wear', 'formal-wear-female', 'woman/formal-wear-female', '<p><span>Formal Wear</span></p>', '', '', '', NULL, 'en'),
(11, 10, 'Casual Wear', 'casual-wear-female', 'woman/casual-wear-female', '<p>Casual Wear</p>', '', '', '', NULL, 'en'),
(12, 11, 'Active Wear', 'active-wear-female', 'woman/active-wear-female', '<p>Active</p>', '', '', '', NULL, 'en'),
(13, 12, 'Footwear', 'footwear-female', 'woman/footwear-female', '<p>Footwear</p>', '', '', '', NULL, 'en'),
(14, 13, 'Girls Clothing', 'girls-clothing', 'kids/girls-clothing', '<p>Girls Clothing</p>', 'Girls Clothing', '', '', NULL, 'en'),
(15, 14, 'Boys Clothing', 'boys-clothing', 'kids/boys-clothing', '<p>Boys Clothing</p>', 'Boys Clothing', 'Boys Fashion', '', NULL, 'en'),
(16, 15, 'Girls Footwear', 'girls-footwear', 'kids/girls-footwear', '<p>Girls Footwear</p>', 'Girls Footwear', 'Girls Fashionable Footwear Collection', '', NULL, 'en'),
(17, 16, 'Boys Footwear', 'boys-footwear', 'kids/boys-footwear', '<p>Boys Footwear</p>', 'Boys Footwear', 'Boys Stylish Footwear Collection', '', NULL, 'en'),
(18, 17, 'Wellness', 'wellness', 'wellness', '<p>Fitness</p>', '', '', '', NULL, 'en'),
(19, 18, 'Downloadable Yoga Tutorial', 'downloadable-yoga-tutorial', 'wellness/downloadable-yoga-tutorial', '<p>Downloadable Yoga Tutorial</p>', '', '', '', NULL, 'en'),
(20, 19, 'E-Books', 'e-books', 'wellness/e-books', '<p>Books Collection</p>', 'Books Collection', 'Books Collection', '', NULL, 'en'),
(21, 20, 'Movie Pass', 'movie-pass', 'wellness/movie-pass', '<p>Movie Pass</p>', 'CineXperience Monthly Movie Pass', 'Immerse yourself in the magic of 10 movies each month without extra charges. Valid nationwide with no blackout dates, this pass offers exclusive perks and concession discounts, making it a must-have for movie enthusiasts.', '', NULL, 'en'),
(22, 21, 'Bookings', 'bookings', '', '<p>Easily manage and sell your booking-based products with our seamless booking system. Whether you offer appointments, rentals, events, or reservations, our solution ensures a smooth experience for both businesses and customers. With real-time availability, flexible scheduling, and automated notifications, you can streamline your booking process effortlessly. Enhance customer convenience and maximize your sales with our powerful booking product solution!</p>', '', '', '', NULL, 'en'),
(23, 22, 'Appointment Booking', 'appointment-booking', '', '<p>Appointment booking allows customers to schedule time slots for services or consultations with businesses or professionals. This system is commonly used in industries such as healthcare, beauty, education, and personal services. It helps streamline scheduling, reduce wait times, and improve customer satisfaction by offering convenient, time-based reservations.</p>', '', '', '', NULL, 'en'),
(24, 23, 'Event Booking', 'event-booking', '', '<p>Event booking allows individuals or groups to register or reserve spots for public or private events such as concerts, workshops, conferences, or parties. It typically includes options for selecting dates, seating types, and ticket categories, providing organizers with efficient attendee management and ensuring a smooth entry process.</p>', '', '', '', NULL, 'en'),
(25, 24, 'Community Hall Bookings', 'community-hall-bookings', '', '<p>Community hall booking enables individuals, organizations, or groups to reserve community spaces for various events such as weddings, meetings, cultural programs, or social gatherings. This system helps manage availability, schedule bookings, and handle logistics like capacity, amenities, and rental duration. It ensures efficient use of public or private halls while offering a convenient way for users to organize their events.</p>', '', '', '', NULL, 'en'),
(26, 25, 'Table Booking', 'table-booking', '', '<p>Table booking enables customers to reserve tables at restaurants, cafes, or dining venues in advance. It helps manage seating capacity, reduce wait times, and provide a better dining experience. This system is especially useful during peak hours, special events, or for accommodating large groups with specific preferences.</p>', '', '', '', NULL, 'en'),
(27, 26, 'Rental Booking', 'rental-booking', '', '<p>Rental booking facilitates the reservation of items or properties for temporary use, such as vehicles, equipment, vacation homes, or meeting spaces. It includes features for selecting rental periods, checking availability, and managing payments. This system supports both short-term and long-term rentals, enhancing convenience for both providers and renters.</p>', '', '', '', NULL, 'en'),
(28, 27, 'Electronics', 'electronics', '', '<p>Explore the latest in consumer electronics, designed to keep you connected, productive, and entertained. Whether you\'re upgrading your devices or looking for smart solutions, we have everything you need.</p>', '', '', '', NULL, 'en'),
(29, 28, 'Mobile Phones & Accessories', 'mobile-phones-accessories', '', '<p>Discover smartphones, chargers, cases, and other essentials for staying connected on the go.</p>', '', '', '', NULL, 'en'),
(30, 29, 'Laptops & Tablets', 'laptops-tablets', '', '<p>Find powerful laptops and portable tablets for work, study, and play.</p>', '', '', '', NULL, 'en'),
(31, 30, 'Audio Devices', 'audio-devices', '', '<p>Shop headphones, earbuds, and speakers to enjoy crystal-clear sound and immersive audio experiences.</p>', '', '', '', NULL, 'en'),
(32, 31, 'Smart Home & Automation', 'smart-home-automation', '', '<p>Make life easier with smart lighting, thermostats, security systems, and more.</p>', '', '', '', NULL, 'en'),
(33, 32, 'Household', 'household', '', '<p>Upgrade your living space with functional and stylish home and kitchen essentials. From cooking to cleaning, find products that enhance comfort and efficiency.</p>', '', '', '', NULL, 'en'),
(34, 33, 'Kitchen Appliances', 'kitchen-appliances', '', '<p>Browse blenders, air fryers, coffee makers, and more to simplify meal prep.</p>', '', '', '', NULL, 'en'),
(35, 34, 'Cookware & Dining', 'cookware-dining', '', '<p>Explore cookware sets, utensils, dinnerware, and serveware for your culinary needs.</p>', '', '', '', NULL, 'en'),
(36, 35, 'Furniture & Decor', 'furniture-decor', '', '<p>Add comfort and charm with sofas, tables, wall art, and home accents.</p>', '', '', '', NULL, 'en'),
(37, 36, 'Cleaning Supplies', 'cleaning-supplies', '', '<p>Keep your space spotless with vacuums, cleaning sprays, brooms, and organizers.</p>', '', '', '', NULL, 'en'),
(38, 37, 'Books & Stationery', 'books-stationery', '', '<p>Ignite your imagination or organize your workspace with a wide selection of books and stationery. Perfect for readers, students, professionals, and artists.</p>', '', '', '', NULL, 'en'),
(39, 38, 'Fiction & Non-Fiction Books', 'fiction-non-fiction-books', '', '<p>Dive into bestselling novels, biographies, self-help, and more.</p>', '', '', '', NULL, 'en'),
(40, 39, 'Educational & Academic', 'educational-academic', '', '<p>Find textbooks, reference materials, and study guides for all ages.</p>', '', '', '', NULL, 'en'),
(41, 40, 'Office Supplies', 'office-supplies', '', '<p>Shop pens, notebooks, planners, and office essentials for productivity.</p>', '', '', '', NULL, 'en'),
(42, 41, 'Art & Craft Materials', 'art-craft-materials', '', '<p>Explore paints, brushes, sketchbooks, and DIY craft kits for creatives.</p>', '', '', '', NULL, 'en'),
