(56, 15, 'أحذية بنات', 'احذية-بنات', '', '<p>أحذية بنات</p>', 'أحذية بنات', 'مجموعة أحذية الفتيات العصرية', '', NULL, 'ar'),
(57, 16, 'أحذية الأولاد', 'احذية-الاولاد', '', '<p>أحذية الأولاد</p>', 'أحذية الأولاد', 'مجموعة الأحذية الأنيقة للأولاد', '', NULL, 'ar'),
(58, 17, 'صحة', 'صحة', '', '<p>صحة</p>', '', '', '', NULL, 'ar'),
