(2402, 'en', NULL, '<p>Reserve a <strong data-start=\"448\" data-end=\"473\">VIP fine dining table</strong> at <strong data-start=\"477\" data-end=\"499\">Skyline Restaurant</strong> with breathtaking city views and a premium experience.</p>', NULL, NULL, NULL, NULL, NULL, NULL, 125, 9, 'en|125|9'),
(2403, 'en', NULL, '<p>Enjoy a <strong data-start=\"589\" data-end=\"620\">luxurious dining experience</strong> at <strong data-start=\"624\" data-end=\"646\">Skyline Restaurant</strong>, offering a <strong data-start=\"659\" data-end=\"680\">private VIP table</strong> with <strong data-start=\"686\" data-end=\"710\">panoramic city views</strong>. This booking includes a <strong data-start=\"736\" data-end=\"795\">welcome drink, priority service, and a dedicated waiter</strong> to ensure an unforgettable evening. Ideal for romantic dinners, business meetings, or special celebrations.</p>', NULL, NULL, NULL, NULL, NULL, NULL, 125, 10, 'en|125|10'),
