INSERT INTO `product_attribute_values` (`id`, `locale`, `channel`, `text_value`, `boolean_value`, `integer_value`, `float_value`, `datetime_value`, `date_value`, `json_value`, `product_id`, `attribute_id`, `unique_id`) VALUES
(3081, 'ar', NULL, 'ابقَ دافئًا وأنيقًا مع سويتشيرت Coastal Breeze الرجالي الأزرق بسحاب. يتميز هذا السويتشيرت العصري بتصميم حديث، مما يجعله مثاليًا للارتداء غير الرسمي والنشط. توفر البطانة الداخلية الناعمة والمريحة الدفء، بينما يسمح الإغلاق بالسحاب الكامل بتنسيق متعدد الاستخدامات والتحكم في درجة الحرارة. الجيوب الأمامية المريحة مثالية للتخزين وإبقاء يديك دافئتين.', NULL, NULL, NULL, NULL, NULL, NULL, 46, 9, 'ar|46|9'),
(3082, 'ar', NULL, '<p>سويتشيرت Coastal Breeze الرجالي الأزرق بسحاب هو رفيقك الموثوق للبقاء دافئًا ومرتاحًا وأنيقًا.</p><br><p>تم تصميم هذا السويتشيرت للرجل العصري الذي يقدر الموضة والوظيفة معًا. يضيف التصميم الأزرق الأنيق لمسة من الذوق المعاصر، مما يجعله مناسبًا لمختلف المناسبات، سواء كنت تقوم بالمهمات أو تذهب إلى صالة الألعاب الرياضية أو تستمتع ببساطة بيوم مريح.</p><br><p>الدفء هو الأولوية القصوى، وهذا السويتشيرت يحققها. البطانة الداخلية ناعمة ومريحة، مما يضمن بقاءك مرتاحًا ودافئًا حتى في الطقس البارد. إنه الإضافة المثالية لخزانة ملابسك عندما تحتاج إلى طبقة إضافية من العزل.</p><br><p>الإغلاق بالسحاب الكامل ليس فقط للأناقة؛ بل يسمح لك بالتحكم في راحتك ودرجة حرارتك بسهولة. يمكنك ارتداء السويتشيرت مغلقًا بالكامل للحصول على أقصى دفء أو فتحه للحصول على مظهر أكثر استرخاءً. هذا التنوع يجعله الخيار المفضل لمختلف الإعدادات.</p><br><p>الراحة هي المفتاح، والجيوب الأمامية توفر ذلك تمامًا. إنها مثالية لتخزين الأساسيات الخاصة بك، سواء كان هاتفك أو محفظتك أو مفاتيحك. بالإضافة إلى ذلك، فهي تحافظ على دفء يديك خلال الأيام الباردة.</p><br><p>مصنوع من مزيج قطني مريح ومتين، تم تصميم هذا السويتشيرت لتحمل الاستخدام اليومي والحفاظ على جاذبيته الأنيقة.</p><br><p>ابقَ دافئًا وأنيقًا مع سويتشيرت Coastal Breeze الرجالي الأزرق بسحاب. هذا السويتشيرت أكثر من مجرد ملابس؛ إنه انعكاس لذوقك العصري والعملي في الموضة. دعه يكون خيارك الموثوق للبقاء مريحًا وأنيقًا في أي موقف، مما يضمن أن تبدو وتشعر بأفضل حال.</p>', NULL, NULL, NULL, NULL, NULL, NULL, 46, 10, 'ar|46|10'),
