(3260, 'ar', NULL, 'PureStride, أحذية رجالية, سنيكرز, حذاء أبيض, حذاء كاجوال, أحذية رياضية, UK7', NULL, NULL, NULL, NULL, NULL, NULL, 71, 17, 'ar|71|17'),
(3261, 'ar', NULL, 'حذاء سنيكرز أبيض كلاسيكي للرجال برباط ونعل مطاطي—راحة ودعم طوال اليوم ومناسب لمختلف الإطلالات.', NULL, NULL, NULL, NULL, NULL, NULL, 71, 18, 'ar|71|18'),
