(3563, 'ar', NULL, 'سنيكرز OceanBreeze للبنات — أزرق مريح', NULL, NULL, NULL, NULL, NULL, NULL, 115, 2, 'ar|115|2'),
(3564, 'ar', NULL, 'سنيكرز خفيف ومبطن للبنات بلون أزرق عصري. خامات قابلة للتنفس ونعل مانع للانزلاق لراحة وأمان أثناء اللعب.', NULL, NULL, NULL, NULL, NULL, NULL, 115, 9, 'ar|115|9'),
(3565, 'ar', NULL, '<p>سنيكرز OceanBreeze الأزرق مصمم للبنات النشيطات اللواتي يحتجن إلى راحة طوال اليوم.</p><br><p>خامات تنفس تساعد على إبقاء القدمين منتعشتين، مع نعل يمنح ثباتًا أفضل أثناء الحركة.</p><br><p>مثالي للمدرسة، التنزه، والأنشطة اليومية.</p>', NULL, NULL, NULL, NULL, NULL, NULL, 115, 10, 'ar|115|10'),
