INSERT INTO `product_flat` (`id`, `sku`, `type`, `product_number`, `name`, `short_description`, `description`, `url_key`, `new`, `featured`, `status`, `meta_title`, `meta_keywords`, `meta_description`, `price`, `special_price`, `special_price_from`, `special_price_to`, `weight`, `created_at`, `locale`, `channel`, `attribute_family_id`, `product_id`, `updated_at`, `parent_id`, `visible_individually`) VALUES
(1, 'ws-blossom-skirt', 'configurable', '', 'Blossom Breeze Cotton Printed Short Skirt', 'Embrace the playful elegance of our Blossom Breeze Cotton Printed Short Skirt. Crafted from high-quality cotton fabric and adorned with a delightful print, this skirt is perfect for those seeking a blend of comfort and style in their summer wardrobe.', '<p>Introducing the Blossom Breeze Cotton Printed Short Skirt, a charming addition to your summer wardrobe. Made from premium quality cotton, this skirt offers a soft and breathable feel, ensuring comfort all day long. The delightful print features blossoms and intricate patterns, adding a touch of playfulness to your ensemble.</p><br><p>The A-line silhouette of the Blossom Breeze skirt is designed to provide a flattering fit, accentuating your curves in all the right ways. The length is just perfect, offering a balance between style and ease of movement, making it ideal for casual outings, picnics, or a day at the beach.</p><br><p>Pair this skirt with a simple tank top or a cropped blouse to complete the look. Add sandals and minimal accessories for a laid-back summer vibe or dress it up with wedges and statement jewelry for a more elevated appearance. The Blossom Breeze Cotton Printed Short Skirt is a versatile piece that effortlessly adapts to your style and the occasion.</p><br><p>Experience the epitome of summer fashion with our Blossom Breeze Cotton Printed Short Skirt. Let the vibrant print and comfortable fabric make a statement as you embrace the sun-kissed season with confidence and style.</p>', 'blossom-breeze-cotton-printed-short-skirt', 1, 1, 1, 'Blossom Breeze Cotton Printed Short Skirt', 'Blossom Breeze Cotton Printed Short Skirt, skirt, women skirt, cotton skirt, printed skirt, short skirt, women fashion, casual wear, blossom, breeze, cotton, printed', 'Experience the epitome of summer fashion with our Blossom Breeze Cotton Printed Short Skirt. Let the vibrant print and comfortable fabric make a statement as you embrace the sun-kissed season with confidence and style.', 0.0000, NULL, NULL, NULL, 0.0000, '2026-08-01 19:41:14', 'en', 'default', 4, 1, '2026-08-01 19:41:15', NULL, 1),
(2, 'ws-blossom-skirt', 'configurable', '', 'تنورة قطنية مطبوعة بنسيم الزهور القصيرة', 'استمتع بأناقة مرحة مع تنورتنا القطنية القصيرة المطبوعة بنسيم الزهور. مصنوعة من قماش قطني عالي الجودة ومزينة بطبعة جميلة، هذه التنورة مثالية لمن يبحث عن مزيج من الراحة والأناقة في خزانة الصيف.', '<p>نقدم لكم تنورة قطنية مطبوعة بنسيم الزهور القصيرة، إضافة ساحرة إلى خزانة ملابسك الصيفية. مصنوعة من قطن عالي الجودة، توفر هذه التنورة ملمسًا ناعمًا وقابلية للتهوية، مما يضمن الراحة طوال اليوم. تتميز الطبعة الجميلة بأزهار ونقوش دقيقة، تضيف لمسة من المرح إلى إطلالتك.</p><br><p>تم تصميم قصة التنورة على شكل حرف A لتمنحك مظهرًا أنيقًا يبرز منحنياتك بأفضل شكل. الطول مثالي، حيث يوفر توازنًا بين الأناقة وسهولة الحركة، مما يجعلها مناسبة للنزهات أو الشاطئ أو الخروجات الكاجوال.</p><br><p>نسقي هذه التنورة مع توب بسيط أو بلوزة قصيرة لإكمال الإطلالة. أضيفي صندلًا وإكسسوارات بسيطة لمظهر صيفي مريح أو ارتديها مع كعب وإكسسوارات بارزة لمظهر أكثر أناقة. تنورة نسيم الزهور القطنية القصيرة قطعة متعددة الاستخدامات تتكيف بسهولة مع أسلوبك والمناسبة.</p><br><p>اختبري قمة الموضة الصيفية مع تنورتنا القطنية القصيرة بنسيم الزهور. دعي الطبعة الزاهية والقماش المريح يعكسان ثقتك وأناقتك في موسم مشمس.</p>', 'blossom-breeze-cotton-printed-short-skirt', 1, 1, 1, 'تنورة قطنية مطبوعة بنسيم الزهور القصيرة', 'تنورة قطنية مطبوعة بنسيم الزهور القصيرة, تنورة, تنورة نسائية, تنورة قطنية, تنورة مطبوعة, تنورة قصيرة, موضة نسائية, ملابس كاجوال, نسيم, زهور, قطن, مطبوعة', 'اختبري قمة الموضة الصيفية مع تنورتنا القطنية القصيرة بنسيم الزهور. دعي الطبعة الزاهية والقماش المريح يعكسان ثقتك وأناقتك في موسم مشمس.', 0.0000, NULL, NULL, NULL, 0.0000, '2026-08-01 19:41:15', 'ar', 'default', 4, 1, '2026-08-01 19:41:15', NULL, 1),
