(269, 'ms-executive-suit', 'configurable', '', 'Executive Elegance Men\'s Formal Office Suit', '<p>Elevate your professional presence with our Executive Elegance Men\'s Formal Office Suit. Meticulously tailored from premium fabrics with impeccable attention to detail, this suit delivers a polished and authoritative look for boardrooms, business meetings, and formal occasions.</p>', '<p>Introducing the Executive Elegance Men\'s Formal Office Suit, the embodiment of professional sophistication. Crafted from a premium polyester-viscose blend with a smooth satin lining, this suit offers both comfort and durability throughout the workday.</p><br><p>The two-button single-breasted jacket features notch lapels, a chest pocket, and two front flap pockets, while the straight-fit trousers complete the streamlined silhouette. Available in classic colors, this suit transitions seamlessly from office hours to evening events.</p><br><p><strong>Key Features:</strong></p><ul><li>Premium polyester-viscose blend fabric</li><li>Smooth satin interior lining</li><li>Two-button single-breasted jacket</li><li>Notch lapels with chest and flap pockets</li><li>Straight-fit matching trousers</li><li>Available in Green and Blue</li></ul>', 'executive-elegance-mens-formal-office-suit', 1, 1, 1, 'Executive Elegance Men\'s Formal Office Suit', 'formal suit, men suit, office suit, business suit, professional wear, men formal wear, executive suit, two-piece suit, blazer, trousers', 'Discover the Executive Elegance Men\'s Formal Office Suit. Premium polyester-viscose blend with satin lining, perfect for business meetings and formal occasions.', 0.0000, NULL, NULL, NULL, 0.0000, '2026-08-01 19:41:39', 'en', 'default', 3, 135, '2026-08-01 19:41:39', NULL, 1),
(270, 'ms-executive-suit', 'configurable', '', 'بدلة رجالية رسمية إكزيكيوتف إليجانس', '<p>ارتقِ بأناقتك المهنية مع بدلتنا الرجالية الرسمية إكزيكيوتف إليجانس. مصممة بعناية من أقمشة فاخرة مع خياطة دقيقة لمظهر احترافي متميز.</p>', '<p>نقدم لكم بدلة إكزيكيوتف إليجانس الرجالية الرسمية، تجسيد الأناقة والاحترافية. مصنوعة من مزيج البوليستر والفسكوز الفاخر مع بطانة ساتان ناعمة. تتميز بقصة عصرية مع سترة بزرين وبنطال مستقيم أنيق. مثالية للاجتماعات والمكاتب والمناسبات الرسمية.</p>', 'executive-elegance-mens-formal-office-suit', 1, 1, 1, 'بدلة رجالية رسمية إكزيكيوتف إليجانس', 'بدلة, رجالية, رسمية, مكتب, أعمال, احترافية', 'بدلة رجالية رسمية إكزيكيوتف إليجانس للمناسبات المهنية والرسمية.', 0.0000, NULL, NULL, NULL, 0.0000, '2026-08-01 19:41:39', 'ar', 'default', 3, 135, '2026-08-01 19:41:39', NULL, 1),
(271, 'ms-executive-suit-green-m', 'simple', '', 'Executive Elegance Men\'s Formal Office Suit-Green-M', '<p>Elevate your professional presence with our Executive Elegance Men\'s Formal Office Suit. Meticulously tailored from premium fabrics with impeccable attention to detail, this suit delivers a polished and authoritative look for boardrooms, business meetings, and formal occasions.</p>', '<p>Introducing the Executive Elegance Men\'s Formal Office Suit, the embodiment of professional sophistication. Crafted from a premium polyester-viscose blend with a smooth satin lining, this suit offers both comfort and durability throughout the workday.</p><br><p>The two-button single-breasted jacket features notch lapels, a chest pocket, and two front flap pockets, while the straight-fit trousers complete the streamlined silhouette. Available in classic colors, this suit transitions seamlessly from office hours to evening events.</p><br><p><strong>Key Features:</strong></p><ul><li>Premium polyester-viscose blend fabric</li><li>Smooth satin interior lining</li><li>Two-button single-breasted jacket</li><li>Notch lapels with chest and flap pockets</li><li>Straight-fit matching trousers</li><li>Available in Green and Blue</li></ul>', 'executive-suit-variant-green-m', 0, 0, 1, 'Executive Elegance Men\'s Formal Office Suit-Green-M', 'formal suit, men suit, office suit, business suit, professional wear, men formal wear, executive suit, two-piece suit, blazer, trousers', 'Discover the Executive Elegance Men\'s Formal Office Suit. Premium polyester-viscose blend with satin lining, perfect for business meetings and formal occasions.', 299.9900, NULL, NULL, NULL, 10.0000, '2026-08-01 19:41:39', 'en', 'default', 3, 136, '2026-08-01 19:41:40', NULL, 0),
